-- =============================================================================
-- 0040 — Stock contado por equipo
-- -----------------------------------------------------------------------------
-- Pedido de Jared (23/10/2026). En cada equipo la tienda elige si cuenta el
-- stock:
-- - contar_stock = false: como hasta ahora, el interruptor "con stock / sin
--   stock" (en_stock). La cantidad no se guarda.
-- - contar_stock = true: stock_cantidad (0 a 99.999) y en_stock lo pone el
--   disparador equipos_stock (con stock = al menos una unidad).
-- La cantidad es solo del panel: el público no la puede leer (permiso por
-- columna) y datos_publicos() manda stock_bajo, la cantidad solo si es de 1 a
-- 5, para el cartel del sitio ("Quedan 3"). Por eso datos_publicos() pasa a
-- security definer: filtra lo público igual que la política equipos_leer
-- (publicado, con stock y del modelo activo) y quita la cantidad.
--
-- crear_equipos_lote acepta también precio_usd (0038), promo_descuento (0039),
-- contar_stock y stock_cantidad.
--
-- Al final, datos_fabrica() (0036) con la instalación nueva de 0037 a 0040.
-- assets/js/datos/demo.js repite las mismas reglas.
-- =============================================================================

alter table public.equipos
  add column contar_stock boolean not null default false,
  add column stock_cantidad integer check (stock_cantidad between 0 and 99999);

create or replace function public.aplicar_stock()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.contar_stock then
    if new.stock_cantidad is null then
      raise exception 'Escriba cuántas unidades tiene (0 o más).' using errcode = '23514';
    end if;
    new.en_stock := new.stock_cantidad > 0;
  else
    new.stock_cantidad := null;
  end if;
  return new;
end $$;

create trigger equipos_stock before insert or update on public.equipos
  for each row execute function public.aplicar_stock();

-- El público lee todas las columnas de equipos menos la cantidad.
revoke select on public.equipos from anon;
grant select (id, modelo_id, condicion, capacidad, precio, fotos, publicado, destacado, descripcion_extra, es_demo,
              bateria_porcentaje, estado_estetico, detalles, incluye, creado_en, actualizado_en, en_stock, color_id,
              color_nombre_mostrar, video, mas_vendido, precio_usd, promo_descuento, contar_stock)
  on public.equipos to anon;

create or replace function public.datos_publicos()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'tienda',  (select to_jsonb(t) from public.tienda t where id = 1),
    'modelos', coalesce((select jsonb_agg(to_jsonb(m) order by m.orden) from public.modelos m where m.activo), '[]'::jsonb),
    'fichas',  coalesce((select jsonb_agg(to_jsonb(f)) from public.fichas f
                          join public.modelos m on m.id = f.modelo_id and m.activo), '[]'::jsonb),
    'colores', coalesce((select jsonb_agg(to_jsonb(c) order by c.modelo_id, c.orden) from public.colores c
                          join public.modelos m on m.id = c.modelo_id and m.activo), '[]'::jsonb),
    'equipos', coalesce((select jsonb_agg((to_jsonb(e) - 'stock_cantidad') || jsonb_build_object('stock_bajo',
                            case when e.contar_stock and e.stock_cantidad between 1 and 5 then e.stock_cantidad end))
                          from public.equipos e
                          join public.modelos m on m.id = e.modelo_id and m.activo
                          where e.publicado and e.en_stock), '[]'::jsonb),
    'resenas', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'tipo', r.tipo, 'ruta', r.ruta, 'texto', r.texto,
                                                             'origen', r.origen, 'origen_otro', r.origen_otro) order by r.orden, r.creado_en)
                          from public.resenas r where (select mostrar_resenas from public.tienda where id = 1)), '[]'::jsonb)
  )
$$;

create or replace function public.crear_equipos_lote(lote jsonb)
returns setof public.equipos
language plpgsql security invoker set search_path = public as $$
declare
  i integer;
  d jsonb;
  fila public.equipos;
begin
  if jsonb_typeof(lote) is distinct from 'array' or jsonb_array_length(lote) = 0 then
    raise exception 'El lote no tiene equipos.' using errcode = '22023';
  end if;
  if jsonb_array_length(lote) > 200 then
    raise exception 'Un lote puede tener hasta 200 equipos.' using errcode = '22023';
  end if;
  for i in 0 .. jsonb_array_length(lote) - 1 loop
    d := lote -> i;
    begin
      if jsonb_typeof(d) is distinct from 'object' then
        raise exception 'Algún dato no tiene el formato correcto. Revise los campos.' using errcode = '22023';
      end if;
      -- El mismo mensaje que demo.js (el check de la tabla solo diría "formato").
      if jsonb_typeof(d -> 'precio') is distinct from 'number' or (d ->> 'precio')::numeric <= 0
         or (d ->> 'precio')::numeric <> trunc((d ->> 'precio')::numeric) then
        raise exception 'El precio debe ser un número entero mayor que 0.' using errcode = '23514';
      end if;
      insert into public.equipos (
        modelo_id, condicion, capacidad, color_id, color_nombre_mostrar, precio, en_stock,
        fotos, video, publicado, destacado, mas_vendido, descripcion_extra,
        bateria_porcentaje, estado_estetico, detalles, incluye,
        precio_usd, promo_descuento, contar_stock, stock_cantidad
      ) values (
        (d ->> 'modelo_id')::bigint,
        d ->> 'condicion',
        d ->> 'capacidad',
        (d ->> 'color_id')::bigint,
        coalesce(d ->> 'color_nombre_mostrar', ''),
        (d ->> 'precio')::bigint,
        coalesce((d ->> 'en_stock')::boolean, true),
        case when jsonb_typeof(d -> 'fotos') = 'array'
             then array(select jsonb_array_elements_text(d -> 'fotos')) else '{}' end,
        coalesce(d ->> 'video', ''),
        coalesce((d ->> 'publicado')::boolean, false),
        coalesce((d ->> 'destacado')::boolean, false),
        coalesce((d ->> 'mas_vendido')::boolean, false),
        coalesce(d ->> 'descripcion_extra', ''),
        (d ->> 'bateria_porcentaje')::smallint,
        d ->> 'estado_estetico',
        coalesce(d ->> 'detalles', ''),
        coalesce(d ->> 'incluye', ''),
        (d ->> 'precio_usd')::bigint,
        (d ->> 'promo_descuento')::smallint,
        coalesce((d ->> 'contar_stock')::boolean, false),
        (d ->> 'stock_cantidad')::integer
      ) returning * into fila;
    exception when others then
      -- Volver a lanzar el error revierte todo el lote (también lo ya insertado).
      raise exception using message = format('Variante %s: %s', i + 1, sqlerrm), errcode = sqlstate;
    end;
    return next fila;
  end loop;
end $$;

revoke execute on function public.crear_equipos_lote(jsonb) from public, anon;
grant execute on function public.crear_equipos_lote(jsonb) to authenticated;

